void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_uint8_t_1_init((sb_queue_uint8_t_1_t *) pulse_queue_1);

  sb_queue_int32_t_1_init((sb_queue_int32_t_1_t *) sample_queue_1);

  sb_queue_int32_t_1_init((sb_queue_int32_t_1_t *) level_queue_1);

  sb_queue_bool_1_init((sb_queue_bool_1_t *) flag_queue_1);

  sb_queue_bool_1_init((sb_queue_bool_1_t *) boolean_value_queue_1);

  sb_queue_char_1_init((sb_queue_char_1_t *) character_value_queue_1);

  sb_queue_int8_t_1_init((sb_queue_int8_t_1_t *) signed_8_value_queue_1);

  sb_queue_int16_t_1_init((sb_queue_int16_t_1_t *) signed_16_value_queue_1);

  sb_queue_uint8_t_1_init((sb_queue_uint8_t_1_t *) unsigned_8_value_queue_1);

  sb_queue_uint16_t_1_init((sb_queue_uint16_t_1_t *) unsigned_16_value_queue_1);

  sb_queue_Exhaustive_Monitor_OperatingState_1_init((sb_queue_Exhaustive_Monitor_OperatingState_1_t *) operating_state_queue_1);

  sb_queue_Exhaustive_Monitor_Samples_1_init((sb_queue_Exhaustive_Monitor_Samples_1_t *) samples_queue_1);

  sb_queue_Exhaustive_Monitor_Telemetry_i_1_init((sb_queue_Exhaustive_Monitor_Telemetry_i_1_t *) telemetry_queue_1);

  producer_producer_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      producer_producer_timeTriggered();
      break;
    default:
      producer_producer_notify(channel);
  }
}
